import 'package:nmea_dashboard/state/common.dart';

// The property sets are generated from the parser source, run `dart run build_runner build`
// after changing any parser.
part 'property_sets.g.dart';

/// Reports whether each property can be generated by the parsers for each network protocol.
extension PropertySupport on Property {
  /// Returns true if any NMEA 0183 parser can generate this property.
  bool get supportedBy0183 => _supportedBy(_nmea0183Properties);

  /// Returns true if any NMEA 2000 parser can generate this property.
  bool get supportedBy2000 => _supportedBy(_nmea2000Properties);

  bool _supportedBy(Set<Property> properties) {
    // Magnetic headings are delivered to the true heading element so count as heading support.
    return properties.contains(this) ||
        (this == Property.heading && properties.contains(Property.headingMag));
  }
}
